using namespace std;

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t;
    cin >> t;
    while (t--) {
        string l, r;
        cin >> l >> r;
        if (l == r) {
            cout << 2 * l.size() << '\n';
            continue;
        }
        int ptr = 0;
        while (ptr < l.size() && l[ptr] == r[ptr]) ptr++;
        if (l[ptr] + 1 < r[ptr]) {
            cout << 2 * ptr << '\n';
        } else {
            int res = 2 * ptr + 1;
            for (int i = ptr + 1; i < l.size(); i++) {
                if (l[i] == '9' && r[i] == '0') res++;
                else break;
            }
            cout << res << '\n';
        }
    }
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

typedef long long ll;
int const maxn = 2e5 + 5;
int a[maxn];
ll pref[maxn], s;

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t;
    cin >> t;
    while (t--) {
        int n, x;
        cin >> n >> s >> x;
        for (int i = 1; i <= n; i++) {
            cin >> a[i];
            pref[i] = pref[i - 1] + a[i];
        }
        ll ans = 0;
        map<ll, int> cnt;
        int lef = 1;
        for (int r = 1; r <= n; r++) {
            if (a[r] > x) cnt.clear(), lef = r + 1;
            else if (a[r] == x) {
                while (lef <= r) {
                    cnt[pref[lef - 1]]++;
                    lef++;
                }
            }
            ans += cnt[pref[r] - s];
        }
        cout << ans << '\n';
    }
    return 0;
}

#include<bits/stdc++.h>

using namespace std;

typedef long long ll;
int const maxn = 2e5 + 5;
int pref[maxn];

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        string s;
        cin >> s;
        ll ans = 0;
        for (int i = 0; i < n; i++) {
            pref[i + 1] = pref[i];
            if (s[i] == '0') pref[i + 1]--;
            else pref[i + 1]++;
        }
        for (int i = 1; i <= n; i++) {
            ans += (ll)i * (n - i + 1);
        }
        sort(pref, pref + n + 1);
        for (int i = 0; i <= n; i++) {
            ans += (ll)pref[i] * (i - (n - i));
        }
        cout << ans / 2 << '\n';
    }
    return 0;
}

