using namespace std;

main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        multiset<int> dp;
        for (int i = 1; i <= n; i++) {
            int l, r;
            cin >> l >> r;
            auto it = dp.upper_bound(r);
            if (it != dp.end()) {
                dp.erase(it);
            }
            dp.insert(l);
            cout << dp.size() << " ";
        }
        cout << '\n';
    }
    return 0;
}
